78\', \'2428311\', \'2429064\', \'2428204\', \'2421343\', \'2431206\', \'2430491\', \'2426682\', \'2426487\', \'2426458\', \'2423575\', \'2422431\', \'2423612\', \'2426625\', \'2428117\', \'2426894\', \'2425461\', \'2426570\', \'2423455\', \'2430777\', \'2426009\', \'2428245\', \'2427269\', \'2430946\', \'2425821\', \'2429986\', \'2429085\', \'2422047\', \'2430789\', \'2420219\', \'2428341\', \'2430444\', \'2426866\', \'2431230\', \'2425839\', \'2430980\', \'2427048\', \'2430597\', \'2420499\', \'2431050\', \'2420271\', \'2426684\', \'2428747\', \'2423523\', \'2431171\', \'2430830\', \'2425325\', \'2428414\', \'2429054\', \'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') AND LOWER(tags) NOT LIKE \'%creator%\' AND tags NOT LIKE \'%SnitchCreators%\' AND gross_sales != 0 AND phone IS NOT NULL AND order_date BETWEEN DATEADD(MONTH, -3, CURRENT_DATE) AND CURRENT_DATE ), order_level_metrics AS ( SELECT phone, order_date, CONCAT(phone, \'-\', order_date) as daily_phone_order_id, ANY_VALUE(customer_id) as customer_id, ANY_VALUE(LOWER(customer_flag)) AS customer_flag, ANY_VALUE(LOWER(loyalty_customer)) AS loyalty_customer, ANY_VALUE(webshopney) AS webshopney, ANY_VALUE(tags) AS tags, ANY_VALUE(payment_channel) AS payment_channel, ANY_VALUE(LOWER(order_status)) AS order_status, ANY_VALUE(is_refund) AS is_refund, SUM(dto_quant) AS total_dto_quant, SUM(cancel_quant) AS total_cancel_quant, SUM(cancel_sales) AS total_cancel_sales, SUM(net_sales) AS total_net_sales, SUM(gross_sales) AS total_gross_sales, SUM(CASE WHEN LOWER(discount_code) IS NOT NULL AND LOWER(discount_code) LIKE \'%rms%\' THEN 0 ELSE discount END) AS total_discount, SUM(tax) AS total_tax, SUM(shipping_price) AS total_shipping_price, SUM(quantity) AS total_quantity, SUM(CASE WHEN discount = 0 THEN quantity END) AS fp_total_quantity, SUM(CASE WHEN IFNULL(slashed_discount, 0) = 0 THEN quantity END) AS nonslashed_total_quantity, SUM(CASE WHEN IFNULL(coupon_discount, 0) = 0 THEN quantity END) AS noncoupon_total_quantity, SUM(CASE WHEN IFNULL(loyalty_discount, 0) = 0 THEN quantity END) AS nonloyalty_total_quantity, SUM(CASE WHEN is_refund = 1 THEN quantity END) AS total_return_quantity, SUM(CASE WHEN is_refund = 1 THEN net_sales END) AS total_return_value FROM base_data_with_category GROUP BY 1, 2 ), distinct_order_categories AS ( SELECT DISTINCT CONCAT(phone, \'-\', order_date) as daily_phone_order_id, l1_category FROM base_data_with_category ), final_attribution_base AS ( SELECT m.*, c.l1_category FROM order_level_metrics m JOIN distinct_order_categories c ON m.daily_phone_order_id = c.daily_phone_order_id ) SELECT f.order_date AS Date, f.l1_category, SUM(f.total_dto_quant) AS dto_quantity, SUM(f.total_cancel_quant) AS cancel_quantity, SUM(f.total_cancel_sales) AS cancel_sales, SUM(f.total_net_sales) AS Total_Sales, SUM(f.total_gross_sales) AS Gross_Sales, SUM(CASE WHEN f.customer_flag = \'new\' THEN f.total_gross_sales ELSE 0 END) AS New_Customer_revenue, SUM(CASE WHEN f.customer_flag != \'new\' THEN f.total_gross_sales ELSE 0 END) AS Repeat_Customer_revenue, SUM(CASE WHEN f.loyalty_customer = \'yes\' THEN f.total_gross_sales ELSE 0 END) AS Loyalty_Customer_revenue, SUM(CASE WHEN f.webshopney = \'Web\' THEN f.total_gross_sales ELSE 0 END) AS web_gross_sales, SUM(CASE WHEN f.customer_flag = \'new\' AND f.webshopney = \'Web\' THEN f.total_gross_sales ELSE 0 END) AS New_Customer_Revenue_web, SUM(CASE WHEN f.customer_flag != \'new\' AND f.webshopney = \'Web\' THEN f.total_gross_sales ELSE 0 END) AS Repeat_Customer_Revenue_web, SUM(CASE WHEN f.loyalty_customer = \'yes\' AND f.webshopney = \'Web\' THEN f.total_gross_sales ELSE 0 END) AS Loyalty_Customer_Revenue_web, SUM(CASE WHEN LOWER(f.tags) LIKE \'%snitch_web%\' THEN f.total_gross_sales ELSE 0 END) AS web2_gross_sales, SUM(CASE WHEN f.customer_flag = \'new\' AND LOWER(f.tags) LIKE \'%snitch_web%\' THEN f.total_gross_sales ELSE 0 END) AS New_Customer_Revenue_web2, SUM(CASE WHEN f.customer_flag != \'new\' AND LOWER(f.tags) LIKE \'%s