Revenue_App_Android, SUM(CASE WHEN f.loyalty_customer = \'yes\' AND f.webshopney = \'Snitch_IOS\' AND f.tags LIKE \'%Snitch_Android%\' THEN f.total_gross_sales ELSE 0 END) AS Loyalty_Customer_Revenue_App_Android, COUNT(DISTINCT f.daily_phone_order_id) AS Total_Orders, COUNT(DISTINCT CASE WHEN f.customer_flag = \'new\' THEN f.daily_phone_order_id END) AS New_Customer_Orders, COUNT(DISTINCT CASE WHEN f.customer_flag != \'new\' THEN f.daily_phone_order_id END) AS Repeat_Customer_Orders, COUNT(DISTINCT CASE WHEN f.loyalty_customer = \'yes\' THEN f.daily_phone_order_id END) AS Loyalty_Customer_Orders, COUNT(DISTINCT CASE WHEN f.webshopney = \'Web\' THEN f.daily_phone_order_id END) AS Web_Orders, COUNT(DISTINCT CASE WHEN LOWER(f.tags) LIKE \'%snitch_web%\' THEN f.daily_phone_order_id END) AS Web2_Orders, COUNT(DISTINCT CASE WHEN f.customer_flag = \'new\' AND f.webshopney = \'Web\' THEN f.daily_phone_order_id END) AS New_Web_Customer_Orders, COUNT(DISTINCT CASE WHEN f.customer_flag != \'new\' AND f.webshopney = \'Web\' THEN f.daily_phone_order_id END) AS Repeat_Web_Customer_Orders, COUNT(DISTINCT CASE WHEN f.loyalty_customer = \'yes\' AND f.webshopney = \'Web\' THEN f.daily_phone_order_id END) AS Loyalty_Web_Customer_Orders, COUNT(DISTINCT CASE WHEN f.customer_flag = \'new\' AND LOWER(f.tags) LIKE \'%snitch_web%\' THEN f.daily_phone_order_id END) AS New_Web2_Customer_Orders, COUNT(DISTINCT CASE WHEN f.customer_flag != \'new\' AND LOWER(f.tags) LIKE \'%snitch_web%\' THEN f.daily_phone_order_id END) AS Repeat_Web2_Customer_Orders, COUNT(DISTINCT CASE WHEN f.loyalty_customer = \'yes\' AND LOWER(f.tags) LIKE \'%snitch_web%\' THEN f.daily_phone_order_id END) AS Loyalty_Web2_Customer_Orders, COUNT(DISTINCT CASE WHEN f.webshopney IN (\'Shopney\', \'Appbrew\') THEN f.daily_phone_order_id END) AS App_Orders, COUNT(DISTINCT CASE WHEN f.customer_flag = \'new\' AND f.webshopney IN (\'Shopney\', \'Appbrew\') THEN f.daily_phone_order_id END) AS New_App_Customer_Orders, COUNT(DISTINCT CA