T(DISTINCT CASE WHEN f.loyalty_customer = \'yes\' THEN f.customer_id END) AS Loyalty_Repeat_Customers, SUM(f.total_discount) AS Total_Discount, SUM(CASE WHEN f.customer_flag = \'new\' THEN f.total_discount ELSE 0 END) AS New_Customer_Discount, SUM(CASE WHEN f.customer_flag != \'new\' THEN f.total_discount ELSE 0 END) AS Repeat_Customer_Discount, SUM(CASE WHEN f.loyalty_customer = \'yes\' THEN f.total_discount ELSE 0 END) AS Loyalty_Customer_Discount, COUNT(DISTINCT CASE WHEN f.payment_channel = \'COD\' THEN f.daily_phone_order_id END) AS COD_orders, COUNT(DISTINCT CASE WHEN f.customer_flag = \'new\' AND f.payment_channel = \'COD\' THEN f.daily_phone_order_id END) AS New_Customer_COD_Orders, COUNT(DISTINCT CASE WHEN f.customer_flag != \'new\' AND f.payment_channel = \'COD\' THEN f.daily_phone_order_id END) AS Repeat_Customer_COD_Orders, SUM(f.total_gross_sales) - SUM(CASE WHEN f.order_status = \'cancelled\' AND f.is_refund = 0 THEN f.total_net_sales ELSE 0 END) AS Gross_SALES_EXCL_CANCL, COUNT(DISTINCT f.daily_phone_order_id) - COUNT(DISTINCT CASE WHEN f.order_status = \'cancelled\' AND f.is_refund = 0 THEN f.daily_phone_order_id END) AS Orders_EXCL_CANCL, COUNT(DISTINCT CASE WHEN f.customer_flag = \'new\' THEN f.daily_phone_order_id END) - COUNT(DISTINCT CASE WHEN f.customer_flag = \'new\' AND f.order_status = \'cancelled\' AND f.is_refund = 0 THEN f.daily_phone_order_id END) AS New_Customer_Orders_EXCL_CANCL, SUM(f.total_discount) - SUM(CASE WHEN f.order_status = \'cancelled\' AND f.is_refund = 0 THEN f.total_discount ELSE 0 END) AS TOTAL_DISCOUNT_EXCL_CANCL, SUM(f.total_tax) - SUM(CASE WHEN f.order_status = \'cancelled\' AND f.is_refund = 0 THEN f.total_tax ELSE 0 END) AS TAX_EXCL_CANCL, SUM(f.total_shipping_price) - SUM(CASE WHEN f.order_status = \'cancelled\' AND f.is_refund = 0 THEN f.total_shipping_price ELSE 0 END) AS SHIPPING_PRICE_EXCL_CANCL, SUM(f.total_quantity) AS TOTAL_QUANTITY, SUM(f.fp_total_quantity) AS FP_TOTAL_QUANTITY, SUM(f.nonslashed_total_quantity) AS nonslashed_TOTAL_QUANTITY, SUM(f.noncoupon_total_quantity) AS noncoupon_TOTAL_QUANTITY, SUM(f.nonloyalty_total_quantity) AS nonloyalty_TOTAL_QUANTITY, SUM(f.total_quantity) - SUM(CASE WHEN f.order_status = \'cancelled\' AND f.is_refund = 0 THEN f.total_quantity ELSE 0 END) AS QUANTITY_EXCL_CANCL, SUM(f.total_return_quantity) AS Return_Quantity, SUM(f.total_return_value) AS Return_Value, COUNT(DISTINCT CASE WHEN f.is_refund = 0 AND f.order_status = \'cancelled\' THEN f.daily_phone_order_id END) AS Cancelled_Orders, COUNT(DISTINCT CASE WHEN f.order_status != \'cancelled\' AND f.is_refund = 0 THEN f.daily_phone_order_id END) AS Net_Orders FROM final_attribution_base f GROUP BY 1, 2 ORDER BY 1, 2;",
